    /**时间处理*/
    private timeProcessing() {
        let posY = 20;
        let tab = Global.gameScreenType == ScreenType.Landscape ? this.actTab.node.getChildByName("landscape").getChildByName("node_root") : this.actTab.node.getChildByName("portrait").getChildByName("node_root");
        tab.getChildByName("tab_2").getChildByName("labTabName").setPosition(tab.getChildByName("tab_2").getChildByName("labTabName").position.x, posY);
        tab.getChildByName("tab_3").getChildByName("labTabName").setPosition(tab.getChildByName("tab_3").getChildByName("labTabName").position.x, posY);
        tab.getChildByName("tab_3").active = false;
        this.curTimesEnd = tab.getChildByName("tab_2").getChildByName("labTabName-001").getComponent(Label);
        this.curTimesEnd.node.active = false;
        this.nextTimesStart = tab.getChildByName("tab_3").getChildByName("labTabName-001").getComponent(Label);
        let tabTimeTips = Global.language == "cn" ? this._tabTimeTips.cn : this._tabTimeTips.en;
        tab.getChildByName("tab_2").getChildByName("labTabName-002").getComponent(Label).string = tabTimeTips[1];
        tab.getChildByName("tab_2").getChildByName("labTabName-002").active = false;
        tab.getChildByName("tab_3").getChildByName("labTabName-002").getComponent(Label).string = tabTimeTips[2];
        this.tabTimeTips = tab.getChildByName("tab_2").getChildByName("labTabName-002").getComponent(Label);
        this.tabTimeTips.node.active = false;
        this.tabTimeTips1 = tab.getChildByName("tab_3").getChildByName("labTabName-002").getComponent(Label);
        clearInterval(this._time);
        clearInterval(this._time2);
        this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
        this._time2 = setInterval(this._pollingEvent1.bind(this), this._pollingtime);
        this._pollingEvent();
        this._pollingEvent1();
    }
    /**当期是否开启*/
    private curIsStart = false
    // 当期时间倒计时
    private _infoTime(message): void {
        //Log.w("数据经过")
        if (!message) {
            this.setCur(0)
            // this.node.active = false;
            return;
        }
        if (!GamesData.rankingSwitch) {
            // this.node.active = false;
            // return;
        }
        clearInterval(this._time);
        clearInterval(this._time2);
        let rewardInfo = new RewardInfoData();
        rewardInfo.startTime = message.startTime * 1000;
        rewardInfo.endTime = message.endTime * 1000;
        rewardInfo.rankId = message.rankId;
        this._data = rewardInfo
        this._rankId = rewardInfo.rankId
        let localTime = Global.svrTimeMS;
        let endTime = rewardInfo.endTime;
        let startTime = rewardInfo.startTime;
        if (!message.starting) {//活动未开始
            this.curIsStart = false
        } else {
            this.curIsStart = true
        }
        let giftTime = this.curIsStart ? endTime - localTime : startTime - localTime;


        if (giftTime > 0) {
            this.curTimesEnd.node.active = true
            this.tabTimeTips.node.active = true
            this.tabTimeTips.string = this.curIsStart ? i18n.tr(2004015) : i18n.tr(2004016)
            // 根据排行榜是否进行显示不同的颜色
            // this.tabTimeTips.color = new Color(238, 203, 147, 255)
            // if (!this.curIsStart) {
            //     this.tabTimeTips.color = new Color(140, 159, 22, 255)
            // }
            this._time = setInterval(this._updateTime.bind(this, rewardInfo), 500);
            this.endtimeShow = true
            if (this.actTabNow == 1)
                this._rootNode.getChildByPath("node_bg/endTimeLab").active = true
            if (this.actTabNow == 1) {
                let endTimeNode = this._rootNode.getChildByPath("node_bg/endTimeLab");
                let localTime = Global.svrTimeMS;
                let lang = Global.language == "cn" ? "cn" : "en";
                endTimeNode.getComponent(Label).string = StringUtil.formatString(!this.curIsStart ? this.StartTips[lang] : this.EndTips[lang], !this.curIsStart ? TimeUtil.timeStamp2String(message.startTime * 1000) : TimeUtil.timeStamp2String(message.endTime * 1000));

            }
        } else {
            this.setCur(0)
            this.tabTimeTips.node.active = false
            this.endtimeShow = false
            this.curTimesEnd.string = i18n.tr(48);
            this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
            this._rootNode.getChildByPath("node_bg/endTimeLab").active = false
        }

    }
    // 设置当期current的位置
    private setCur(posY) {
        // Log.w("weizhi", posY)
        let tab = Global.gameScreenType == ScreenType.Landscape ? this.actTab.node.getChildByName("landscape").getChildByName("node_root") : this.actTab.node.getChildByName("portrait").getChildByName("node_root")
        tab.getChildByName("tab_2").getChildByName("labTabName").setPosition(tab.getChildByName("tab_2").getChildByName("labTabName").position.x, posY)
    }
    private endtimeShow = false
    /**更新剩余时间 */
    private _updateTime(rewardInfo) {
        if (!GamesData.rankingSwitch) {
            // this.node.active = false;
            // return;
        }
        this.node.active = true;

        let localTime = Global.svrTimeMS;
        let endTime = rewardInfo.endTime;
        let startTime = rewardInfo.startTime;
        let giftTime = this.curIsStart ? endTime - localTime : startTime - localTime;
        let timeStr: string;
        //Log.w("时间", giftTime)
        if (giftTime <= 0) {
            clearInterval(this._time);
            timeStr = "";
            this.endtimeShow = false
            this._rootNode.getChildByPath("node_bg/endTimeLab").active = false
            this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
            this.tabTimeTips.node.active = false
            this.setCur(0)
        } else {
            if (this.actTabNow == 1)
                this._rootNode.getChildByPath("node_bg/endTimeLab").active = true
            this.setCur(20)
            this.curTimesEnd.node.active = true
            this.tabTimeTips.node.active = true
            this.tabTimeTips.string = this.curIsStart ? i18n.tr(2004015) : i18n.tr(2004016)
            // // 根据排行榜是否进行显示不同的颜色
            // this.tabTimeTips.color = new Color(238, 203, 147, 255)
            // if (!this.curIsStart) {
            //     this.tabTimeTips.color = new Color(140, 159, 22, 255)
            // }
            timeStr = LeagueTablesEntrance.instance._formatTime(giftTime);
            this.endtimeShow = true
        }
        this.curTimesEnd.string = timeStr;
        // // 根据排行榜是否进行显示不同的颜色
        // this.curTimesEnd.color = new Color(238, 203, 147, 255)
        // if (!this.curIsStart) {
        //     this.curTimesEnd.color = new Color(140, 159, 22, 255)
        // }

    }
