    /**下一期时间*/
    private _infoNextTime(message): void {
        // Log.w("下一期时间", message)
        if (!message) {
            return;
        }
        this.nextRankId = message.rankId
        if (!GamesData.rankingSwitch) {
            // this.node.active = false;
            // return;
        }
        let tab = Global.gameScreenType == ScreenType.Landscape ? this.actTab.node.getChildByName("landscape").getChildByName("node_root") : this.actTab.node.getChildByName("portrait").getChildByName("node_root")
        tab.getChildByName("tab_3").active = true;

        clearInterval(this._time2);
        let rewardInfo = new RewardInfoData();
        rewardInfo.startTime = message.startTime * 1000;
        rewardInfo.endTime = message.endTime * 1000;
        rewardInfo.rankId = message.rankId;

        let localTime = Global.svrTimeMS;
        let startTime = rewardInfo.startTime;
        let giftTime = startTime - localTime;
        let lang = Global.language == "cn" ? "cn" : "en";
        this._rootNode.getChildByPath("node_bg/startTimeLab").getComponent(Label).string = StringUtil.formatString(this.StartTips[lang], TimeUtil.timeStamp2String(startTime))
        //Log.w("timeStr", this._rootNode.getChildByPath("node_bg/startTimeLab").getComponent(Label).string)
        if (rewardInfo.startTime - localTime > 0) {//活动未开始
            // this.node.active = false;
            // this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
            // return;
        }
        //Log.w("giftTime", giftTime)
        if (giftTime > 0) {
            this._time2 = setInterval(this._updateNextTime.bind(this, rewardInfo.startTime), 500);
        } else {
            this.nextTimesStart.string = "Started";
            // this.nextTimesStart.color = new Color(140, 159, 22, 255)
            // this.tabTimeTips1.color = new Color(140, 159, 22, 255)
            let tab = Global.gameScreenType == ScreenType.Landscape ? this.actTab.node.getChildByName("landscape").getChildByName("node_root") : this.actTab.node.getChildByName("portrait").getChildByName("node_root")
            tab.getChildByName("tab_3").active = false
            this._time2 = setInterval(this._pollingEvent1.bind(this), this._pollingtime);
        }

    }

    /**更新下一期时间 */
    private _updateNextTime(startTime) {
        if (!GamesData.rankingSwitch) {
            // this.node.active = false;
            // return;
        }
        this.node.active = true;

        let localTime = Global.svrTimeMS;
        let giftTime = startTime - localTime;
        let timeStr: string;
        if (giftTime <= 0) {
            clearInterval(this._time2);
            timeStr = "Started";
            let tab = Global.gameScreenType == ScreenType.Landscape ? this.actTab.node.getChildByName("landscape").getChildByName("node_root") : this.actTab.node.getChildByName("portrait").getChildByName("node_root")
            tab.getChildByName("tab_3").active = false
            this._time2 = setInterval(this._pollingEvent1.bind(this), this._pollingtime);
        } else {
            timeStr = LeagueTablesEntrance.instance._formatTime(giftTime);
        }
        this.nextTimesStart.string = timeStr;
    }


