    // 把后端数据格式转化为前端所需 往期数据
    private _getRankDataFromLast(data: any): RankingData {
        // //Log.d("排行榜往期数据：", data)
        // data = { "award": { "rankType": 1, "rankTypeProps": [{ "cardId": 174, "num": 1 }], "rankTypeScore": "" }, "player": { "account": "*********110", "aid": null, "ranking": 1, "type": 1, "uid": 1701191862382071800, "value": 24 } }
        if (!data) return;
        let player = data.player;
        let reward = data.award;
        let rankData = new RankingData(player.ranking, player.account, player.uid, player.value);
        if (reward) {
            rankData.itemBaseVos = [];
            switch (reward.rankType) {
                case 1: // 虚宝卡
                    for (let prop of reward.rankTypeProps) {
                        rankData.itemBaseVos.push(<ItemBaseVo>{
                            propId: prop.cardId,
                            propType: ItemType.Xbk,
                            num: prop.num,
                        });
                    }
                    break;
                case 2: // 积分卡
                    rankData.itemBaseVos.push(<ItemBaseVo>{
                        propId: 0,
                        propType: ItemType.Score,
                        num: Number(reward.rankTypeScore),
                    });
                    break;
            }
        }
        return rankData;
    }
