    private updateLastRank(message?: any) {
        // Log.e("收到message,", message)
        if (this.firstGetLastRank) {
            if (message && message?.rankId) {
                this._lastRankId = message.rankId
                this.firstGetLastRank = false
            }
            return
        }
        //Log.e("收到message,", message)
        if (!message || !message.rankingList || message.rankingList.length == 0) {
            this._rootNode.getChildByPath("node_bg/noDataNode").getComponent(Label).string = i18n.tr(2004017)
            this._rootNode.getChildByPath("node_bg/noDataNode").active = true;
            return;
        }

        this.lastRankObj = message;
        let rankDatas = message.rankingList;
        let srcRankItem = this._rootNode.getChildByPath("node_bg/last_Node/my_data");
        let toggleNode = this._rootNode.getChildByPath("node_bg/phb_Node/phb_list/view/content").getChildByName("item")
        let content = this._rootNode.getChildByPath("node_bg/last_Node/last_list/view/content");
        content.removeAllChildren();
        // this.previousReward = {
        //     "banner": "bbbb",
        //     "bannerLink": "12345",
        //     "rankComment": "hahahahahaha",
        //     "rewards": []
        // }
        for (let i = 0; i < rankDatas.length; ++i) {
            // this.previousReward.rewards.push(rankDatas[i].award)
            let rankItem = instantiate(toggleNode);
            let rankData = this._getRankDataFromLast(rankDatas[i]);
            this.setRankItem(rankItem, rankData, message.type);
            // ResManager.Instance().load(BUNDLE_NAME.gamesCommon, "resources/texture/phb/phb_list_2_2/spriteFrame", SpriteFrame, null, (cacheData) => {
            //     rankItem.getComponent(Sprite).spriteFrame = cacheData.data as SpriteFrame;
            // });
            content.addChild(rankItem);
        }

        let myRankNode = srcRankItem;
        let myRankData = this._getRankDataFromLast(message.playerRanking);
        if (myRankData) {
            this.setRankItem(myRankNode, myRankData, message.type);
            myRankNode.active = true;
        } else myRankNode.active = false;
    }

    private actTabData: TabData = new TabData();
    private actTabNow: number = 1;

    /**当前点击的子标签*/
    private subTabNow: number = 0;
    private subTabData: TabData = new TabData();

    /**
     * 
     * @param type 点击的tab 0,1子tab---2,3,4左边父tab
     * @param issub 
     * @returns 
     */
    private _showNode(type: number, issub = false) {
        // Log.e("点击", type, issub)
        if (!issub) {
            this.actTabData.type = type;
            this.actTabData.issub = issub;
        } else {
            this.subTabData.type = type;
            this.subTabData.issub = issub;
        }
        if (type <= 1) this.subTabNow = type
        // Log.e("subTabNow", this.subTabNow)
        let subLength = Global.language == "cn" ? this._subTabName.cn.length : this._subTabName.en.length
        if (this._index == type + subLength && !issub || this._subindex == type && issub) {
            if (!this._inChange) {
                return;
            }
        }
        if (!issub) {
            type += subLength
            this.actTabNow = type - subLength;
            //Log.w("type,", type)
            this._index = type
        } else {
            this._subindex = type;
        }

        //Log.w("点击", type, issub)
        this._removeRank();
        this._hideNode();
        this._subindex == 1 ? this.getReward() : this.getRank();
    }

