                else
                    GameCommonManager.getInstance()._c2sActRankRewards(this._rankId);
                this._rootNode.getChildByPath("node_bg/reward_Node").active = true;
                // Log.e("zzz当期", this._rankId)
                if (this.endtimeShow && this.actTabNow == 1)
                    this._rootNode.getChildByPath("node_bg/endTimeLab").active = true;
                this._rootNode.getChildByPath("node_bg/updateTips").active = true;
