/**
 * @description 彩金按钮
 * @author guohuo
 */
import { Node, Component, Label, _decorator, Sprite, tween, Tween, Vec3, NodeEventType } from "cc";
import { UIButton } from "../../../../../scripts/framework/ui/basic_ui/UIButton";
import { WinningsMgr } from "./WinningsMgr";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../GameEventType";
import { RollValue } from "../../RollValue";
import { GameCommonModel } from "../../GameCommonModel";
import { GameComUtils } from "../../utils/GameComUtils";
import { Global } from "../../../../../scripts/main/Global";
import { UIManager } from "../../../../../scripts/framework/ui/UIManager";
import { UIID_GAME } from "../../UIGameDefined";
import { GameUtils } from "../../../../../scripts/common/utils/GameUtil";
import GamesData from "../../GamesData";
import StringUtil from "../../../../../scripts/common/utils/StringUtil";
import { StatConst } from "../../stat/StatConst";
import { ScreenType } from "../../../../../scripts/framework/ui/UIView";
const { ccclass, property } = _decorator;

@ccclass("WinningsBtn")
export class WinningsBtn extends Component {
    @property(UIButton)
    private btn: UIButton;
    @property(Sprite)
    private iconLv: Sprite;
    @property(RollValue)
    private rollVal: RollValue;
    @property(Node)
    private nodeMask: Node;
    @property(Node)
    private nodeMove: Node;

    private curIndex: number = -1;

    private timer1: number = 0;
    private timer2: number = 0;
    private timer3: number = 0;

    moveBeginX: number = 224;
    moveEndX: number = 25;
    readonly iconLvY: number = 7.85;
    /** jackpot 彩金请求间隔时长，也是彩金跳动时长 */
    static readonly ReqInterval: number = 60;
    readonly SwitchInterval: number = 10;
    public isDisplayingRecord: boolean = false;

    private _isInit: boolean = false;
    init() {
        if (this._isInit) return;
        this._isInit = true;

        this.nodeMask.active = false;

        this.addEvents();
        WinningsMgr.getInstance().c2sWinningsJackpots();
    }

    addEvents() {
        Eventer.getInstance().offName(GameEventType.winnings_jackpots, this);
        Eventer.getInstance().offName(GameEventType.winnings_notice, this);
        // Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);
        Eventer.getInstance().on(GameEventType.winnings_jackpots, this.onWinningsJackpots, this);
        Eventer.getInstance().on(GameEventType.winnings_notice, this.onSbWinning, this);
        // Eventer.getInstance().on(GameEventType.OnReceiveSlotInfo, this.onLoginSuccess, this);

        this.btn.touchEndedFun = this.onClick.bind(this);
        this.nodeMove.on(NodeEventType.TOUCH_END, this.onClick.bind(this), this);
    }

    onLoginSuccess() {
        Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);
        WinningsMgr.getInstance().c2sWinningsJackpots();
    }

    onWinningsJackpots() {
        let curDatas = WinningsMgr.getInstance().curDatas || [];
        if (curDatas.length == 0) {
            this.iconLv.spriteFrame = null;
            this.rollVal.setText("");
        }
        if (!this.timer2) {
            this.timer2 = setInterval(this.switchJackpot.bind(this), this.SwitchInterval * 1000);
        }
        if (this.curIndex == -1) {
            this.switchJackpot();
        }

        this.updateVal();
        this.showOneWinning();
    }

    onSbWinning() {
        this.showOneWinning();
    }

    showOneWinning() {
        if (this.isDisplayingRecord) return;

        let newWinning = WinningsMgr.getInstance().shiftOneWinning();
        if (!newWinning) {
            this.nodeMask.active = false;
            Eventer.getInstance().emit(GameEventType.winnings_notice_display);
            return;
        }

        this.isDisplayingRecord = true;
        this.nodeMask.active = true;
        Eventer.getInstance().emit(GameEventType.winnings_notice_display);
        let lab1 = this.nodeMove.getChildByName("lab1").getComponent(Label);
        let lab2 = this.nodeMove.getChildByName("lab2").getComponent(Label);
        let lab3 = this.nodeMove.getChildByName("lab3").getComponent(Label);
        let lab4 = this.nodeMove.getChildByName("lab4").getComponent(Label);
        let icon = this.nodeMove.getChildByName("icon").getComponent(Sprite);

        lab2.string = StringUtil.blurrStr(newWinning.name);
        lab3.string = "Jackpot " + (newWinning.level || 'x');
        lab4.string = GamesData.formatValue(newWinning.amount * GameCommonModel.getInstance().coinRate, 2, false, true);
        GameComUtils.setGameIcon(newWinning.gameId, icon);

        let reverse = false;
        let logoNode = this.node.parent.parent.parent;
        let menuNode = logoNode.getChildByName("menuNode");

        if (menuNode.active) {
            reverse = menuNode.position.x > 0 ? false : true;
        } else {
            let pos = logoNode.position;
            if (Global.gameScreenType == ScreenType.Landscape) {
                reverse = pos.x > 0 ? true : false;
            } else {
                reverse = pos.y > 0 ? true : false;
            }
        }

        if (reverse) {
            this.moveBeginX = 224;
            this.moveEndX = 25;
        } else {
            this.moveBeginX = -224;
            this.moveEndX = -25;
        }

        this.nodeMove.setPosition(this.moveBeginX, 0);
        Tween.stopAllByTarget(this.nodeMove);
        new Tween(this.nodeMove)
            .to(0.5, { position: new Vec3(this.moveEndX, 0) }, { easing: "backOut" })
            .delay(3)
            .to(0.3, { position: new Vec3(this.moveBeginX, 0) })
            .call(this.showOneWinningEnd.bind(this))
            .start();
    }

    /** 发现位置跟之前不一致，要更新内部缓动 设置位置，停留1s，收起来 */
    setRecordNewPos(posX: number) {
        if (!this.isDisplayingRecord) return;

        if (posX != this.nodeMask.position.x) {
            this.nodeMask.setPosition(posX, 0);

            let reverse = false;
            let pos = this.node.parent.parent.parent.position;
            if (Global.gameScreenType == ScreenType.Landscape) {
                reverse = pos.x > 0 ? true : false;
            } else {
                reverse = pos.y > 0 ? true : false;
            }

            if (reverse) {
                this.moveBeginX = 224;
                this.moveEndX = 25;
            } else {
                this.moveBeginX = -224;
                this.moveEndX = -25;
            }

            this.nodeMove.setPosition(this.moveEndX, 0);
            Tween.stopAllByTarget(this.nodeMove);
            new Tween(this.nodeMove)
                .delay(1)
                .to(0.3, { position: new Vec3(this.moveBeginX, 0) })
                .call(this.showOneWinningEnd.bind(this))
                .start();
        }
    }

    showOneWinningEnd() {
        this.isDisplayingRecord = false;
        this.showOneWinning();
    }

    updateVal() {
        let curDatas = WinningsMgr.getInstance().curDatas;
        if (!curDatas || curDatas.length == 0) return;

        let curData = curDatas[this.curIndex];
        let showVal = Number(curData.poolAmount) * GameCommonModel.getInstance().coinRate;
        this.rollVal.setText(Global.currencyName + GameComUtils.numToKM(showVal, true));
    }

    protected update(dt: number): void {
        this.updateVal();
    }

    switchJackpot() {
        let curDatas = WinningsMgr.getInstance().curDatas;
        if (!curDatas || curDatas.length == 0) {
            clearInterval(this.timer2);
            this.timer2 = 0;
            this.curIndex = -1;
            return;
        }
        this.curIndex = (this.curIndex + 1) % curDatas.length;
        let curData = curDatas[this.curIndex];
        GameComUtils.setIcon(`resources/texture/winnings/jackpot${curData.level}/spriteFrame`, this.iconLv);
        let showVal = Number(curData.poolAmount) * GameCommonModel.getInstance().coinRate;
        showVal = Number(GamesData.formatValue(showVal, 2, false, true));
        this.rollVal.setText(Global.currencyName + GameComUtils.numToKM(showVal, true));

        new Tween(this.iconLv.node)
            .to(0.1, { position: new Vec3(-5, this.iconLvY) })
            .to(0.2, { position: new Vec3(5, this.iconLvY) })
            .to(0.2, { position: new Vec3(-5, this.iconLvY) })
            .to(0.1, { position: new Vec3(0, this.iconLvY) })
            .start();
    }

    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.winnings_jackpots, this);
        Eventer.getInstance().offName(GameEventType.winnings_notice, this);
        Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);

        clearTimeout(this.timer1);
        clearTimeout(this.timer2);
        clearTimeout(this.timer3);
    }

    onClick() {
        GameComUtils.c2sStat(StatConst.CLICK_BONUS_ICON);
        // UIManager.getInstance().open(UIID_GAME.WinningsView);
    }
}

