import { _decorator, Component, Node, Sprite, instantiate, SpriteFrame, UITransform, CCInteger } from 'cc';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { BmpWordCfgVo } from '../GameCommonModel';
const { ccclass, property,requireComponent } = _decorator;

/** bmp文本组件 */
@ccclass('BmpLableComp')
export class BmpLableComp extends Component {
    @property(CCInteger)
    public maxW: number=0;
    @property(Node)
    private txtNode: Node;

    public bundleName: string;
    public atlasPath: string;
    public fontName: string;

    private _txtNodeList: Node[];
    private _nodePoolList: Node[];
    start() {
        this.txtNode.active = false;
    }

    // update(deltaTime: number) {
    // }

    public onDestroy() {
        // this.removeListener();
       this._txtNodeList=null;
       this._nodePoolList=null;
    }

    private _string:string;
    public get string():string
    {
        return this._string;
    }
    public set string(str: string)
    {
        this.text(str);
    }

    public setInfo(wordFontVo:BmpWordCfgVo):void
    {
        if(!wordFontVo)
        {
            Log.e("文字配置没有值！！");
            return;
        }
        this.bundleName=wordFontVo.bundleName;
        this.atlasPath=wordFontVo.atlasPath;
        this.fontName=wordFontVo.fontName;
    }
    public text(str: string): void {
        this._string=str;
        this.cleanTxt();
        let mURL: string;
        let myNode: Node;
        let str2: string;
        let txtW:number=0;
        let i: number;
        let len: number = str.length;
        for (i = 0; i < len; i++) {
            str2 = str.charAt(i);
            if (!str2) {
                continue;
            }
            if (str2.length < 1 || str2 == "" || str2 == " ") {
                continue;
            }
            myNode = this.getNewNode();
            myNode.active = true;
            this.node.addChild(myNode);
            this._txtNodeList.push(myNode);
            mURL = this.atlasPath + "/" + this.fontName + str2 + "/spriteFrame";
            ResManager.Instance().load(this.bundleName, mURL, SpriteFrame, () => { }, (evt: any) => {
                myNode.getComponent(Sprite).spriteFrame = evt.data;
            });
            txtW+=myNode.getComponent(UITransform).contentSize.width;
        }
        if(this.maxW)
        {
            let mScale:number=1;
            if(txtW>this.maxW)
            {
                mScale =this.maxW/txtW;
            }
            this.node.setScale(mScale,mScale,mScale);
        }
    }

    public setTxtByUrl(mURL:string):void
    {
        let myNode: Node;
        myNode = this.getNewNode();
        myNode.active = true;
        this.node.addChild(myNode);
        this._txtNodeList.push(myNode);
        ResManager.Instance().load(this.bundleName, mURL, SpriteFrame, () => { }, (evt: any) => {
            myNode.getComponent(Sprite).spriteFrame = evt.data;
        });

        if(this.maxW)
        {
            let txtW:number=0;
            txtW+=myNode.getComponent(UITransform).contentSize.width;
            let mScale:number=1;
            if(txtW>this.maxW)
            {
                mScale =this.maxW/txtW;
            }
            this.node.setScale(mScale,mScale,mScale);
        }
    }

    private getNewNode(): Node {
        if (this._nodePoolList && this._nodePoolList.length > 0) {
            return this._nodePoolList.pop();
        }
        return instantiate(this.txtNode);
    }

    public cleanTxt(): void {
        if (!this._txtNodeList) {
            this._txtNodeList = [];
            return;
        }
        if (this._txtNodeList.length < 1) {
            return;
        }

        if (!this._nodePoolList) {
            this._nodePoolList = [];
        }
        let txtN: Node;
        for (txtN of this._txtNodeList) {
            if (txtN.parent) {
                txtN.parent.removeChild(txtN);
            }
            this._nodePoolList.push(txtN);
        }
        this._txtNodeList = [];
    }
}

