import { _decorator, Component, Node, Color } from 'cc';
const { ccclass, property } = _decorator;

class GameColorUtil {
    private _green: Color;
    public get green(): Color {
        if (!this._green) {
            this._green = new Color().fromHEX(`#00e015`)
        }
        return this._green;
    }

    private _yellow: Color;
    public get yellow(): Color {
        if (!this._yellow) {
            this._yellow = new Color().fromHEX(`#e8cf00`)
        }
        return this._yellow;
    }

    private _red: Color;
    public get red(): Color {
        if (!this._red) {
            this._red = new Color().fromHEX(`#ff0000`)
        }
        return this._red;
    }

    private _gray: Color;
    public get gray(): Color {
        if (!this._gray) {
            this._gray = new Color().fromHEX(`#C0C0C0`)
        }
        return this._gray;
    }

    private _white: Color;
    public get white(): Color {
        if (!this._white) {
            this._white = new Color().fromHEX(`#ffffff`)
        }
        return this._white;
    }

}
export default new GameColorUtil();

