import { Node, NodeEventType, Sprite, color, js } from "cc";

function isArray(obj) {
    return Array.isArray(obj) ||
        (typeof obj === 'object' && Object.prototype.toString.call(obj) === '[object Array]');
}

function isString(obj) {
    return typeof obj == 'string' || Object.prototype.toString.call(obj) == '[object String]';
}

function isNumber(obj) {
    return typeof obj == 'number' || Object.prototype.toString.call(obj) == '[object Number]';
}

function isObject(obj) {
    return obj.__nativeObj !== undefined ||
        ( typeof obj === "object" && Object.prototype.toString.call(obj) === '[object Object]' );
}

function isFunction(obj) {
    return typeof obj == 'function';
}

function isUndefined(obj) {
    return typeof obj === 'undefined';
}

/** 输出空格函数 */
function blank(num) {
	var res = '';
	for (var i = 0; i < num; i++) {
		res += '	';
	}
	return res;
}   

/** 计算JSON对象数据个数 */
function jsonLen(jsonObj) {
	var length = 0;
	for (var item in jsonObj) {
	  	length++;
	}
	return length;
}



export class GameToolsFunc {
	//打印对象
	public static dump(obj, deep = 0) {
		if (!obj || !(isArray(obj) || isObject(obj))) {
			Log.d("data is not a Array or object!");
			return;
		}

		deep = deep || 0;
		var html = blank(deep);
		var len = isArray(obj) ? obj.length : jsonLen(obj);
		var i = 0; 

		if (deep == 0) {
			Log.d("{");
		}

		for (var key in obj) {
			var value = obj[key];
			if (isArray(value) || (value && isObject(value))) {
				// console.log("{0}{1} = {".format(blank(deep+1), key));
                Log.d(js.formatStr("%s%s = {", blank(deep+1), key));
				GameToolsFunc.dump(value, deep + 1);
			}
			else {
				html = blank(deep + 1);
				// console.log("{0}{1} : {2}".format(html, key, value));
                Log.d(js.formatStr("%s%s : %s", html, key, value));
			}

			if (i == len -1) {
				html = blank(deep) + "}";
				Log.d(html);
			};
			i++;
		}

		if (len <= 0) {
			html = blank(deep) + "}";
			Log.d(html);
		}
	}

	public static cloneObj(obj, newObj) {
		if (!obj || !(isArray(obj) || isObject(obj))) {
			return;
		}

		for (var key in obj) {
			newObj[key] = obj[key];
		}
	}

	public static onClickEvent(btnNode:Node, callback:Function)
    { 
        btnNode.on(NodeEventType.TOUCH_START, function () {
            btnNode.getComponent(Sprite).color = color(200, 200, 200, 255);
        }, this);

        btnNode.on(NodeEventType.TOUCH_END, function () {
            btnNode.getComponent(Sprite).color = color(255, 255, 255, 255);

            callback();
        }, this);

        btnNode.on(NodeEventType.TOUCH_CANCEL, function () {
            btnNode.getComponent(Sprite).color = color(255, 255, 255, 255);
        }, this);
    }
}