import { Component, Label, Node, ScrollView, _decorator } from "cc";
import { GameComUtils } from "../../utils/GameComUtils";
import { BagItem } from "../bag/BagItem";
import { ItemType } from "../bag/BagModel";
import { Global } from "../../../../../scripts/main/Global";
import { ScreenType } from "../../../../../scripts/framework/ui/UIView";
const { ccclass, property } = _decorator;

@ccclass("VipPageItem")
export class VipPageItem extends Component {
    @property(Label)
    vipLab: Label;
    @property(Node)
    items: Node;
    @property(Node)
    scroll: Node;

    private ScrollW = 400;
    private ScrollX = 333;
    private ScrollY = -133.765;

    setData(vipCfg: any) {
        let rewardTips = this.node.getChildByName("labRewardTips");
        let rewards = this.node.getChildByName("rewards");
        let vipLab2 = this.node.getChildByName("vipLab2").getComponent(Label);
        if (!vipCfg) {
            this.vipLab.string = '0';
            this.items.removeAllChildren();
            vipLab2.string = 'VIP0';
            rewards.active = false;
            rewardTips.active = true;
            return;
        }

        if (Global.gameScreenType == ScreenType.Landscape) {
            this.ScrollW = 400;
            this.ScrollX = 480.591;
            this.ScrollY = -67.043;
        } else {
            this.ScrollW = 380;
            this.ScrollX = 446.253;
            this.ScrollY = -39.705;
        }

        rewards.active = true;
        rewardTips.active = false;
        this.vipLab.string = vipCfg.level.toString();
        vipLab2.string = 'VIP' + vipCfg.level.toString();
        this.items.removeAllChildren();

        let itemNum = 0;
        if (vipCfg.reward > 0) {
            GameComUtils.loadItem((item: BagItem) => {
                item.setEasyData(0, ItemType.Score, vipCfg.reward);
                this.items.addChild(item.node);
            });
            itemNum++;
        }

        if (vipCfg.props) {
            let props: any[] = JSON.parse(vipCfg.props);
            for (let i = 0; i < props.length; ++i) {
                let prop = props[i];
                GameComUtils.loadItem((item: BagItem) => {
                    item.setEasyData(Number(prop.prop_id), Number(prop.prop_type), Number(prop.num));
                    this.items.addChild(item.node);
                });
            }
            itemNum += props.length;
        }

        if (itemNum < 4) {
            let x = this.ScrollX + (this.ScrollW - itemNum * 130 + 20) / 2 * 0.8;
            this.scroll.setPosition(x, this.ScrollY);
        } else {
            this.scroll.setPosition(this.ScrollX, this.ScrollY);
        }
    }

}
