import { _decorator, Component, Node } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import GameSocketManager, { C2S_ProtocolParams } from '../gameSocket/GameSocketManager';
import { EventFunVo, GameManagerI } from '../libs/gamesInterface';
const { ccclass, property } = _decorator;

/** 游戏manager的基类 */
@ccclass('GameBaseManager')
export class GameBaseManager implements GameManagerI {
    /** 类名 */
    public name: string;
    /** 游戏内事件监听注册list */
    public eventList: Array<EventFunVo>;

    /**@description 初始化,表层可重写，创建时自动调用  */
    public init(...args: any[]): any {
    }
    /** 注册协议监听 */
    public registerMsgListener(): void {
        // 例子：
        // GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams>(GameProtocolId.PAYOUTBONUS, this._s2cPayOutBonus, this);
    }
    /**@description 清理数据,表层可重写 */
    public clean(): void { }

    /**
     * initEvent 底层调用，表层不需要调用
     */
    public initEvent(): void {
        if (!this.eventList || this.eventList.length < 1) {
            return;
        }

        let i: number = 0;
        let len: number = this.eventList.length;
        let eventVo: EventFunVo;
        for (i = 0; i < len; i++) {
            eventVo = this.eventList[i];
            Eventer.getInstance().on(eventVo.eventName, eventVo.callBackFun, eventVo.target);
        }
    }
    /** 底层调用，表层不需要调用 */
    public removeAllEvent(): void {
        if (!this.eventList || this.eventList.length < 1) {
            return;
        }
        let i: number = 0;
        let len: number = this.eventList.length;
        let eventVo: EventFunVo;
        for (i = 0; i < len; i++) {
            eventVo = this.eventList[i];
            Eventer.getInstance().offName(eventVo.eventName, eventVo.target);
        }
        this.eventList = null;
    }

    /** 添加单个Eventer */
    public addEvent(eventVo: EventFunVo): void {
        if (!this.eventList || this.eventList.length < 1) {
            this.eventList = [];
        }
        this.eventList.push(eventVo);
        Eventer.getInstance().on(eventVo.eventName, eventVo.callBackFun, eventVo.target);
    }
    /** 移除单个Eventer */
    public removeEvent(eventVo: EventFunVo): void {
        if (this.eventList && this.eventList.length > 0) {
            let i: number = 0;
            let len: number = this.eventList.length;
            for (i = 0; i < len; i++) {
                let iterator = this.eventList[i];
                if (!iterator) {
                    continue;
                }
                if (iterator.eventName != eventVo.eventName) {
                    continue;
                }
                if (iterator.target == eventVo.target) {
                    this.eventList.splice(i, 1);
                }
            }
        }

        Eventer.getInstance().offName(eventVo.eventName, eventVo.target);
    }

    /**
    * 发送数据包
    * @param code 协议编码
    * @param msgObj:message, object
    * @returns 
    */
    public sendPack(protocolId: string, msgObj: any) {
        let msg = {
            type: protocolId,
            message: msgObj
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(protocolId, msg);
    }
}

