/**
 * @description VIP详情界面
 * @author guohuo
 */
import { _decorator, find, Node, Sprite, SpriteFrame, PageView, Component, ToggleContainer, instantiate, Toggle, Label, ProgressBar, Tween, tween, TweenAction, Vec3 } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { Global } from '../../../../../scripts/main/Global';
import { GameEventType } from '../../GameEventType';
import { VipMgr } from './VipMgr';
import { VipPageItem } from './VipPageItem';
import { Tips } from '../../../../../scripts/common/components/Tips';
import ComponentMgr from '../../../../../scripts/mgr/ComponentMgr';
import StringUtil from '../../../../../scripts/common/utils/StringUtil';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { UIGameDefined, UIID_GAME } from '../../UIGameDefined';
import { GameCommonModel } from '../../GameCommonModel';
const { ccclass, property } = _decorator;

@ccclass('VipDlg')
export class VipDlg extends UIView {
    @property({ type: Label, visible: true })
    private curVipLab: Label;
    @property({ type: Label, visible: true })
    private nxtVipLab: Label;
    @property({ type: ProgressBar, visible: true })
    private progressBar: ProgressBar;
    @property({ type: Label, visible: true })
    private progressLab: Label;
    @property({ type: Label, visible: true })
    private tipsLab: Label;
    @property({ type: VipPageItem, visible: true })
    private curPage: VipPageItem;
    @property({ type: VipPageItem, visible: true })
    private nxtPage: VipPageItem;
    @property({ type: Node, visible: true })
    private content: Node;
    @property({ type: Node, visible: true })
    private panelNode: Node;


    @property({ type: UIButton, visible: true })
    private leftBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private rightBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private helpBtn: UIButton;
    @property({ type: UIButton, visible: true })
    private closeBtn: UIButton;

    private curIndex: number = -2;
    private len: number = 0;
    private moving: boolean = false;
    private pageWidth: number = 660;

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    start() {

    }

    public onOpen() {
        this.addEvents();

        this.onScreenSwitch();

        VipMgr.getInstance().c2sVipDetail();
        VipMgr.getInstance().c2sVipAllCfgs(); //改为每次打开请求
        VipMgr.getInstance().c2sVipRules(); //改为每次打开请求
    }

    private addEvents() {
        Eventer.getInstance().on(GameEventType.vip_detail, this.onVipDetail, this);
        Eventer.getInstance().on(GameEventType.vip_all_cfg, this.onVipAllCfgs, this);
        Eventer.getInstance().on(GameEventType.vip_rule, this.updateVipExpRule, this);
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }
    public onDestroy() {
        Eventer.getInstance().offName(GameEventType.vip_detail, this);
        Eventer.getInstance().offName(GameEventType.vip_all_cfg, this);
        Eventer.getInstance().offName(GameEventType.vip_rule, this);
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    private updateBtnEvent() {
        this.closeBtn.touchEndedFun = this.onCloseClicked.bind(this);
        this.leftBtn.touchEndedFun = this.onLeftClicked.bind(this);
        this.rightBtn.touchEndedFun = this.onRightClicked.bind(this);
        this.helpBtn.touchEndedFun = this.onHelpClicked.bind(this);
    }

    private onScreenSwitch(): void {
        let h = this.node.getChildByName("panelNode");
        let v = this.node.getChildByName("panelNode_v");
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.panelNode = h;
            v.active = false;
            this.pageWidth = 660;
        } else {
            this.panelNode = v;
            h.active = false;
            this.pageWidth = 600;
        }

        this.panelNode.active = true;
        this.curVipLab = this.panelNode.getChildByPath("top/curVipLab").getComponent(Label);
        this.nxtVipLab = this.panelNode.getChildByPath("top/nxtVipLab").getComponent(Label);
        this.progressBar = this.panelNode.getChildByPath("top/progressBar").getComponent(ProgressBar);
        this.progressLab = this.panelNode.getChildByPath("top/progressBar/progressLab").getComponent(Label);
        this.tipsLab = this.panelNode.getChildByPath("top/tipsLab").getComponent(Label);
        this.curPage = this.panelNode.getChildByPath("view/content/curPage").getComponent(VipPageItem);
        this.nxtPage = this.panelNode.getChildByPath("view/content/nxtPage").getComponent(VipPageItem);
        this.content = this.panelNode.getChildByPath("view/content");
        this.closeBtn = this.panelNode.getChildByPath("bgNode/closeBtn").getComponent(UIButton);
        this.leftBtn = this.panelNode.getChildByName("leftBtn").getComponent(UIButton);
        this.rightBtn = this.panelNode.getChildByName("rightBtn").getComponent(UIButton);
        this.helpBtn = this.panelNode.getChildByName("helpBtn").getComponent(UIButton);
        this.updateBtnEvent();

        this.updateView(this.curIndex);
        this.updateVipExpRule();
    }

    private onVipDetail(msg: any) {
        this.updateView();
    }

    private onVipAllCfgs() {
        this.updateView();
    }

    private updateVipExpRule() {
        let vipRules = VipMgr.getInstance().vipRules;
        if (!vipRules) return this.tipsLab.string = "";
        this.tipsLab.string = StringUtil.formatString("{0} coin spent earns {1} VIP exp", vipRules.coin * GameCommonModel.getInstance().coinRate, vipRules.valAdd);
    }

    updateView(index?) {
        let vipData = VipMgr.getInstance().vipData;
        let vipCfgs = VipMgr.getInstance().vipCfgs;
        // if (!vipCfgs) VipMgr.getInstance().c2sVipAllCfgs();
        // if (!vipData || !vipCfgs) return;

        if (!vipCfgs || vipCfgs.length == 0 || !vipData) {
            // Log.e("VipDlg: ", "no data!!!");
            this.curPage.setData(null);
            this.leftBtn.node.active = this.rightBtn.node.active = false;
            return;
        }

        vipCfgs.sort((a, b) => {
            return a.level - b.level;
        });


        let len = vipCfgs.length;
        let curVipLv = vipData.level;
        let maxVipLv = vipCfgs[len - 1].level;

        let curIndex: number = -1;
        for (let i = 0; i < len; ++i) {
            if (vipCfgs[i].level == curVipLv) {
                curIndex = i;
                break;
            }
        }

        let nxtIndex = curIndex + 1;
        this.curVipLab.string = "VIP" + curVipLv.toString();
        if (curVipLv < maxVipLv) {
            let nxtVipCfg = vipCfgs[nxtIndex];
            let preVal = vipData.growthValue;
            let curVal = preVal > nxtVipCfg.value ? nxtVipCfg.value : preVal;
            this.nxtVipLab.string = "VIP" + nxtVipCfg.level.toString();
            curVal = Math.floor(curVal);
            this.progressBar.progress = curVal / nxtVipCfg.value;
            this.progressLab.string = curVal + "/" + nxtVipCfg.value;
            this.nxtVipLab.node.active = true;
        } else {
            this.progressBar.progress = 1;
            let curVipCfg = vipCfgs[curIndex];
            this.progressLab.string = curVipCfg.value + "/" + curVipCfg.value;
            this.nxtVipLab.node.active = false;
        }

        if (index !== undefined && index != -2) curIndex = index;
        this.len = len;
        this.curIndex = curIndex;
        this.curPage.setData(vipCfgs[this.curIndex]);
        this.curPage.node.setPosition(0, 0);
        this.curPage.node.active = true;
        this.nxtPage.node.active = false;

        this.leftBtn.node.active = this.curIndex > -1;
        this.rightBtn.node.active = this.curIndex < this.len - 1;
    }

    switchNextPage(val: number) {
        let nxtIndex = this.curIndex + val;
        if (nxtIndex < -1 || nxtIndex > this.len - 1) return;
        if (this.moving) {
            ComponentMgr.showTips("please try later");
            return;
        }

        let vipCfgs = VipMgr.getInstance().vipCfgs;
        let newX = this.pageWidth * val
        let nxtCfg = vipCfgs[nxtIndex];
        this.nxtPage.setData(nxtCfg);
        this.nxtPage.node.setPosition(newX, 0);
        this.nxtPage.node.active = true;

        this.moving = true;
        let newPos = new Vec3(-newX, 0);
        new Tween(this.content).to(0.4, { position: newPos }, { easing: "backOut" })
            .call(() => {
                this.content.setPosition(0, 0);
                let tmpPage = this.curPage;
                this.curPage = this.nxtPage;
                this.nxtPage = tmpPage;
                this.curPage.node.setPosition(0, 0);
                this.nxtPage.node.active = false;
                this.curIndex = nxtIndex;
                this.moving = false;

                this.leftBtn.node.active = this.curIndex > -1;
                this.rightBtn.node.active = this.curIndex < this.len - 1;
            }).start();
    }

    onLeftClicked() {
        this.switchNextPage(-1);
    }

    onRightClicked() {
        this.switchNextPage(1);
    }

    getTips(rules: any) {
        let tips = "";
        let lang = Global.language;
        let ruleStrs = [rules.vipRule, rules.valRule];
        for (let i = 0; i < ruleStrs.length; ++i) {
            let ruleStr = ruleStrs[i];
            if (!ruleStr) continue;
            let rule = JSON.parse(ruleStr);
            if (!rule) continue;
            if (Number(rule.is_i18n) && rule.language) {
                for (let data of rule.language) {
                    if (data.lang == lang) {
                        tips += data.value;
                        break;
                    }
                }
            } else {
                tips += rule.default_value;
            }
            tips += "\n\n";
        }

        return tips;
    }

    onHelpClicked() {
        let openVipDlg = () => {
            let rules = VipMgr.getInstance().vipRules;
            let tips = this.getTips(rules);
            UIManager.getInstance().open(UIID_GAME.UIComHelpDlg, tips);
        }
        let vipRules = VipMgr.getInstance().vipRules;
        if (!vipRules) {
            VipMgr.getInstance().c2sVipRules(openVipDlg);
            return;
        }

        openVipDlg();
    }

    onCloseClicked() {
        this.close();
        // Global.gameScreenType = Global.gameScreenType == ScreenType.Landscape ? ScreenType.Portrait : ScreenType.Landscape;
        // Eventer.getInstance().emit(GameEventType.ScreenSwitch);
    }

}

