    /** 运营活动开关 */
    public s2cActSwitchStatus(data: S2C_ProtocolParams<ActSwitchStatusVo_s2c>) {
        let msg = data.message;
        this.setActSwitch(ActType.BackPack, msg.backpack ? 1 : 0);
        this.setActSwitch(ActType.Ranking, msg.ranking ? 1 : 0);
        this.setActSwitch(ActType.Task, msg.task ? 1 : 0);
        this.setActSwitch(ActType.Vip, msg.vip ? 1 : 0);
        this.setActSwitch(ActType.Winnings, msg.prize ? 1 : 0);
        Eventer.getInstance().emit(GameEventType.ActSwitchStatus);
    }

    /** 运营活动开关 */
    public s2cActSwitchNotice(data: S2C_ProtocolParams<ActSwitchNoticeVo_s2c>) {
        if (!data.message)
            return;
        this.setActSwitch(data.message.type, data.message.status);
        Eventer.getInstance().emit(GameEventType.ActSwitchStatus);
    }
    private setActSwitch(type: number, open: number) {
        switch (type) {
            case ActType.Task:
                GamesData.taskSwitch = open; break;
            case ActType.Ranking:
                GamesData.rankingSwitch = open; break;
            case ActType.Vip:
                GamesData.vipSwitch = open; break;
            case ActType.BackPack:
                GamesData.backpackSwitch = open; break;
            case ActType.Winnings:
                GamesData.winningsSwitch = open; break;
        }

        if (!GamesData.taskSwitch)
            UIManager.getInstance().closeToUI(UIID_GAME.GameTaskView);
        if (!GamesData.vipSwitch)
            UIManager.getInstance().closeToUI(UIID_GAME.UIVipDlg);
        if (!GamesData.rankingSwitch)
            UIManager.getInstance().closeToUI(UIID_GAME.UILeagueTables);
        if (!GamesData.backpackSwitch)
            UIManager.getInstance().closeToUI(UIID_GAME.UIBagView);
        if (!GamesData.winningsSwitch)
            UIManager.getInstance().closeToUI(UIID_GAME.WinningsView);
    }

