    /**背包相关协议 */
    private bagListPage1ToNReqing: boolean = false; // 背包列表从1页到n页请求中
    public c2sActBagPage1ToN() {
        if (this.bagListPage1ToNReqing) return;
        this.c2sActBag(1);
        this.bagListPage1ToNReqing = true;
    }
    private c2sActBag(pageNo: number, pageSize: number = BagModel.size) {
        let cts: C2S_ProtocolParams<any> = {
            type: GameProtocolId.act_bag,
            message: {
                pageNo: pageNo,
                pageSize: pageSize,
                lang: Global.language
            }
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.act_bag, cts);
    }
    private s2cActBag(msg: S2C_ProtocolParams<ActBagVo_s2c>) {
        if (!msg.succ) return;

        BagModel.getInstance().updateBagList(msg.message);

        Eventer.getInstance().emit(GameEventType.act_bag, msg.message);

        // 分页每隔100ms请求下一页，直到完毕
        let data = msg.message;
        let delay = 100;
        if (this.bagListPage1ToNReqing && data.current < data.pages) {
            setTimeout(() => {
                this.c2sActBag(data.current + 1, data.size);
            }, delay);
        } else {
            this.bagListPage1ToNReqing = false;
        }
    }

