    /**
     * 通过后台获取币种配置信息
       @param {function} success 
       @param {function} error
       @param {any} thisObject
     */
    public c2sCoinTypeInfo(): void {
        let url: string = "";
        let pack: HttpReqPack = HttpReqPack.create(GameHttpData.getCoinTypeCfg, url, HttpMethod.GET);
        HttpMgr.Instance().send(pack, null, this.s2cCoinTypeInfo.bind(this));
    }

    private s2cCoinTypeInfo(s2c: HttpRespPack) {
        if (s2c && s2c.data && s2c.data.code == 20000) {
            let data: any = s2c.data.data;
            if (!Array.isArray(data)) {
                GamesData.coin_type = data.coin_type;
                GamesData.max_length = data.max_length;
                GamesData.point = data.is_point == "1" ? 2 : 0;
                GamesData.isSeparation = data.is_separation;
                GamesData.ctlArea = data.ctl_area;
            }
        }
        else {
            //Log.e(s2c.msg);
        }
    }

