    /**
    * 发送心跳包
    */
    public sendHeartbeat(): void {
        if (!GameSocketManager.getInstance().isStartGame) {
            return;
        }
        if (!GameSocketManager.getInstance().closeHeartBeat) {
            let msg: C2S_ProtocolParams<HeatBeatVo_s2c> = { type: GameProtocolId.HEART, message: { time: Date.now() } };
            GameSocketManager.getInstance().sendMessage(GameProtocolId.HEART, msg);
            this._model.sentHeartTime = Date.now();
        }
    }

