    /** 
     * 游戏埋点
     * webSocket
     * @param list 事件
     */
    public c2sMark(obj: { [key: string]: any }) {
        if (Global.playback)
            return;
        if (GameCommonModel.getInstance().userType != User_Type.Normal)
            return;
        let msgObj = {
            type: GameProtocolId.MARK,
            message: obj
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.MARK, msgObj);
    }

    /** 
     * 游戏埋点
     * 短链接
     * @param key 事件
     * @param data 数据对象
     */
    public c2javaMarkByShort(key, data) {
        if (Global.debug)
            return;
        if (Global.playback)
            return;
        let event = {
            type: key,
            token: Global.token,
            timestamp: Date.now(),
            data: data
        };
        let body = {
            event: '',
            sign: ''
        }
        body.event = JSON.stringify(event);
        body.sign = new md5().hex_md5(body.event);
        let json = JSON.stringify(body);
        let pack: HttpReqPack = HttpReqPack.create(`${GameHttpData.report}`, json, HttpMethod.POST);
        HttpMgr.Instance().send(pack);
    }

