    /**
     * 上报数据
     * @param type 1:网络问题 2:游戏报错 3:无操作重连 6:进入游戏
     * @param error 错误信息
     */
    public report(type: ReportType, error: string = "") {
        return;
        let strValue;
        if (type == null) {
            strValue = sys.localStorage.getItem(GameHttpData.LOCAL_KEY_ERRORLOG);
            if (!strValue) {
                return;
            }
            let pack: HttpReqPack = HttpReqPack.create(GameHttpData.errorLog, strValue);
            HttpMgr.Instance().send(pack, null, (msg: HttpRespPack, userdata: any) => {
                if (msg.data.code == 1000) {
                    sys.localStorage.removeItem(GameHttpData.LOCAL_KEY_ERRORLOG);
                }
                else {
                    sys.localStorage.setItem(GameHttpData.LOCAL_KEY_ERRORLOG, strValue);
                }
            });
            return;
        }

        strValue = this.getReportValue(type, error);
        if (type == ReportType.nocdrop) {
            sys.localStorage.setItem(GameHttpData.LOCAL_KEY_ERRORLOG, strValue);
        }
        else {
            let pack: HttpReqPack = HttpReqPack.create(GameHttpData.errorLog, strValue);
            HttpMgr.Instance().send(pack, null, (msg: HttpRespPack, userdata: any) => {
                if (msg.data.code == 1000) {
                    sys.localStorage.removeItem(GameHttpData.LOCAL_KEY_ERRORLOG);
                }
                else {
                    sys.localStorage.setItem(GameHttpData.LOCAL_KEY_ERRORLOG, strValue);
                }
            });
        }
    }

    private getReportValue(type: ReportType, error: string): string {
        let strValue = sys.localStorage.getItem(GameHttpData.LOCAL_KEY_ERRORLOG);
        let errorLog = strValue ? JSON.parse(strValue).client_info : [];
        let info = {
            game_id: GamesData.gameId,
            uid: GamesData.userId,
            plat_type: Global.osid,
            drop_type: type,
            drop_param: error,
            ctime: Math.floor(Date.now() / 1000),
            app_type: 2
        }
        error//Log.push(info);
        strValue = JSON.stringify({ client_info: errorLog });
        return strValue;
    }

    private _reportErrdropFun: (this: Window, ev: any) => any;
    /** 游戏报错 */
    private reportErrdrop(e): void {
        this.report(ReportType.errdrop, `filename: ${e.filename} lineno: ${e.lineno} colno: ${e.colno} err: ${e.message}`);
    }


