    /** 超时字典游戏中每帧检测 */
    private _overtimeDic: { [key: string]: number } = {};

    /** 设置超时，每个类型只有一个计时器 */
    public setOutTimeFun(type: string, timeOut: number = 10000): void {
        this._overtimeDic[type] = this._model.serverTime + timeOut;
        //Log.d(this._overtimeDic);
    }

    /** 在超时字典中移除 */
    public delOvertimeDic(type: string): void {
        if (!this._overtimeDic[type]) {
            return;
        }
        this._overtimeDic[type] = null;
        delete this._overtimeDic[type];
    }

    /** 游戏中每帧检测 */
    public checkTimeOut(): void {
        if (!this._overtimeDic) {
            return;
        }
        let timeType: string;
        for (timeType in this._overtimeDic) {
            //超时弹窗
            if (this._overtimeDic[timeType] && this._model.serverTime >= this._overtimeDic[timeType]) {
                UIUtils.showPopupView(11000);
                this.cleanOtDic();
                return;
            }
        }
    }

    /**
     * 清空 _overtimeDic
     */
    private cleanOtDic(): void {
        let timeType: string;
        for (timeType in this._overtimeDic) {
            this._overtimeDic[timeType] = null;
            delete this._overtimeDic[timeType];
        }
        this._overtimeDic = {};
    }

