    public async reLogin(): Promise<void> {
        // 版本检测
        await this.checkAppConfig();
        GamesData.stopBgMusic();
        Eventer.getInstance().on(Events.BundleExit, this.onExit, this);
        UIManager.getInstance().open(UIID_GAME.UIGameLoading);
        UIManager.getInstance().open(UIID.UICover);
        GameCommonModel.getInstance().receiveSlotInfo = false;

        this.changeScreen();
        UIManager.getInstance().closeToUI(UIID.UIPopup);
        UIManager.getInstance().closeToUI(UIID_GAME.UIComActMenu);
        let gameType: EGAME_TYPE = this._model.getGameTypeByGameId(GamesData.gameId);
        if (gameType == EGAME_TYPE.FISHING) {
            UIManager.getInstance().closeToUI(UIID_GAME.UIChooseRoomType);
            UIManager.getInstance().closeToUI(UIID_GAME.UIFishingHelp);
        }
        else if (gameType == EGAME_TYPE.SLOTS) {
            UIManager.getInstance().closeToUI(UIID_GAME.UIRollHelp1);
        } else if (gameType == EGAME_TYPE.MO_GAME) {
            UIManager.getInstance().closeToUI(UIID_GAME.UIAniNotice);
            this.closeIntro()
        }
        else { }

        GamesData.resetStartLoadingTime();
        EntryManager.getInstance().exitBundle(GamesData.gameId.toString(), false);
        GameSocketManager.getInstance().close();
        AudioManager.Instance().stopAllEffect(false);

        this._model.reLogin();
    }

    /** 检测APP版本 */
    private async checkAppConfig() {
        return new Promise(async (resolve, reject) => {
            let url = `${Global.cdn}/${GameConst.APP_GAMES_CONFIG}?v=${Global.svrTimeMS}`
            await RemoteLoader.Instance()
                .loadRemoteJson(url)
                .then((data: any) => {
                    let jsonMinor = data.json;
                    if (jsonMinor) {
                        if (Global.appVersion != jsonMinor.version) {
                            window.location.reload();
                        }
                    }
                    resolve(null);
                })
        })
    }

    private onExit(bundle: string): void {
        if (bundle != GamesData.gameId + "") {
            return;
        }

        Eventer.getInstance().offName(Events.BundleExit, this);
        EntryManager.getInstance().enterBundle(GamesData.gameId + "");

        window.removeEventListener('error', this._reportErrdropFun);
        this._reportErrdropFun = null;
    }

    private clean(): void {
        GamesData.clean();
        this._model.clean();
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().offName(GameEventType.SpinBtnSwitch, this);
        Eventer.getInstance().offName(GameEventType.RollMoneyChange, this);
        Eventer.getInstance().offName(GameEventType.RollBackgroundClick, this);
        Eventer.getInstance().offName(GameEventType.RollReduceAutoTime, this);
        Eventer.getInstance().offName(Events.ButtonClickEvent, this);
        Eventer.getInstance().offName(Events.UIPopupBtn, this);
        Eventer.getInstance().offName(Events.CloseGameSocketEvent, this);
        Eventer.getInstance().offName(Events.ScreenSwitchEvent, this);
        Eventer.getInstance().offName(Events.StatMarkEvent, this);
    }
