import { _decorator, Label, Layers, Node, Tween, tween, UITransform, Vec3 } from "cc";
import { UIView, UIZIndex } from "../../../../scripts/framework/ui/UIView";
const { ccclass, property } = _decorator;

@ccclass("UIAniNotice")
export class UIAniNotice extends UIView {

    @property({ displayName: "跑马灯节点", type: Node })
    marquee: Node = null!;
    @property({ displayName: "跑马灯文本节点", type: Node })
    marqueeMsgNode: Node;

    /** 跑马灯文本列表 */
    private _marTextList: string[] = [];
    /** 跑马灯播放次数 */
    private _marPlayTime: number = 0;
    /** 跑马灯总播放次数 */
    private _marMaxTime: number = 2;
    /** 跑马灯移动速度 L / ms */
    private _marMoveSpeed: number = 0.11;
    /** 跑马灯是否移动中 */
    private _marMoving: boolean = false;
    /** 跑马灯文本列表 */
    private _marLabsList: Node[] = [];


    start() {
        this.setZIndex(UIZIndex.max - 1);
    }

    onLoad() {
        this.hideMarquee();
    }

    /**
     * 播放跑马灯
     * @param text 文本
     */
    playMarquee(text: string) {
        this._marTextList.push(text);
        this.nextMarquee();
    }

    private nextMarquee() {
        if (this._marMoving) {
            return;
        }

        let text = this._marTextList.shift();
        if (!text) {
            this.hideMarquee();
            return;
        }
        this._marMoving = true;
        this.marquee.active = true;

        let strLength = 100;
        let splictTime = Math.floor(text.length / strLength);
        for (let i = 0; i <= splictTime; i++) {
            let str = text.slice(i * strLength, (i + 1) * strLength);
            let lab = this.setLab(str);
            this._marLabsList.push(lab);
        }

        // this.marqueeMsgNode.active = false;
        // setTimeout(this.drawing.bind(this), 0)
        this.scheduleOnce(this.drawing.bind(this), 0);
    }

    private drawing() {
        let strWidth = 0;
        for (let i = 0; i < this._marLabsList.length; i++) {
            let lab = this._marLabsList[i];
            strWidth += lab.getComponent(UITransform).width;
        }
        // this.marqueeMes.getComponent(Label).string = text;
        // this.marqueeMes.getComponent(Label).updateRenderData(true);
        let width = this.marqueeMsgNode.getComponent(UITransform).width = strWidth;
        let sx = this.marquee.getComponent(UITransform).width / 2 + width / 2;
        let ex = -sx;
        let mt = (sx - ex) / this._marMoveSpeed;
        this.marqueeMsgNode.setPosition(new Vec3(sx));
        this.marqueeMsgNode.active = true;

        Tween.stopAllByTarget(this.marqueeMsgNode);
        tween(this.marqueeMsgNode)
            .to(mt / 1000, { position: new Vec3(ex) })
            .call(() => {
                this.marqueeMsgNode.setPosition(new Vec3(sx));
            })
            .union()
            .repeat(this._marMaxTime)
            .call(() => {
                this._marMoving = false;
                this.destoryLabs();
                this.nextMarquee(); //下一条
            })
            .start();

    }

    /**
     * 文本
     */
    private setLab(str: string): Node {
        let node = new Node();
        node.layer = Layers.Enum.UI_2D;
        let lab = node.addComponent(Label);
        lab.fontSize = 18;
        lab.string = str;
        // lab.updateRenderData(true);
        this.marqueeMsgNode.addChild(node);
        return node;
    }

    private hideMarquee() {
        this.marquee.active = false;
    }

    private destoryLabs() {
        for (let i = this._marLabsList.length - 1; i >= 0; i--) {
            let element = this._marLabsList[i];
            element.removeFromParent();
            this._marLabsList.splice(i, 1);
        }
        this._marLabsList = [];
    }
}