import { Node, NodeEventType, _decorator } from "cc";
import { Eventer } from "../../../../scripts/framework/Eventer";
import { UIView, UIZIndex } from "../../../../scripts/framework/ui/UIView";
import { Global } from "../../../../scripts/main/Global";
import { GameEventType } from "../GameEventType";
import { UIButtonState } from "../../../../scripts/framework/ui/basic_ui/UIButtonState";
import AudioManager from "../../../../scripts/framework/manager/AudioManager";
const { ccclass, property } = _decorator;

@ccclass('PlaybackView')
export class PlaybackView extends UIView {

    @property(Node)
    public mask: Node;
    @property(UIButtonState)
    public replayBtn: UIButtonState;

    start() {
        this.node.zIndex = UIZIndex.playback;
        this.mask.active = false;
        this.replayBtn.node.active = false;
        this.initEvent();
    }

    initEvent() {
        this.replayBtn.touchBeganFun = this.onReplay.bind(this);
        this.node.on(NodeEventType.TOUCH_END, this.onTouch, this);
    }

    openReplay() {
        Global.playbackFinish = true;
        this.mask.active = true;
        this.replayBtn.node.active = true;
    }

    private onTouch() {
        AudioManager.Instance().replayMusic();
    }

    private onReplay() {
        this.mask.active = false;
        this.replayBtn.node.active = false;
        Eventer.getInstance().emit(GameEventType.OnReplayPlayback);
    }

    protected onDestroy(): void {
        this.node.off(NodeEventType.TOUCH_END, this.onTouch, this);
    }
}