import { _decorator, Component, Prefab, instantiate, EventTouch, NodeEventType, Node, SpriteFrame, Sprite, UITransform, ScrollView, size, Label, RichText } from 'cc';
import { ScreenType, UIView, UIZIndex } from '../../../../../scripts/framework/ui/UIView';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { UIButtonState } from '../../../../../scripts/framework/ui/basic_ui/UIButtonState';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
import { GameComUtils } from '../../utils/GameComUtils';
const { ccclass, property } = _decorator;

@ccclass('ComHelpDlg')
export class ComHelpDlg extends UIView {
    private _uiList: { [key: string]: Node } = {};

    init(...args): void {
        this.node.zIndex = UIZIndex.actUI;
    }

    onLoad(): void {
        this.initUI();
        this.bindEvent();
    }

    start() {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    onScreenSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this._uiList["panelNode"].angle = 0;
            // this._uiList["panelNode"].setScale(1, 1);
        } else {
            this._uiList["panelNode"].angle = 90;
            // this._uiList["panelNode"].setScale(0.75, 0.75);
        }
    }


    protected onDestroy(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }

    public initUI() {
        this.SerializableUIControlNode(this.node);
    }

    public bindEvent() {
        let closeBtn = this._uiList["closeBtn"];
        closeBtn.getComponent(UIButton).touchEndedFun = this.close.bind(this);
    }

    /**
     * 
     * @param tips '<p><span style="color: #bfedd2;">Here he comes,
     * </span><span style="color: #fbeeb8;"> wearing cool </span><span style="color: #f8cac6;">sunglasses</span>,
     *  <span style="color: #eccafa;">puffing on a big cigar,</span> <span style="color: #c2e0f4;">hanging bombs</span>, 
     * <strong>carrying a heavy</strong> <em>Gatling gun to swim</em><u> towards all fish</u>, try to catch him, it will bring you a surprise.</p>'
     */
    public onOpen(tips: string): void {

        let str = GameComUtils.decodeHtmlEntities(tips);
        let rt = this._uiList["descLab"].getComponent(RichText);
        rt.string = str;
        if (str != '') {
            this._uiList['noDataNode'].active = false;
        } else {
            this._uiList['noDataNode'].active = true;
        }


        this.onScreenSwitch();
    }

    private SerializableUIControlNode(root: Node) {
        if (!root) {
            return;
        }
        let children = root.children;
        for (let k in children) {
            let child = children[k];
            let name = child.name;
            this._uiList[name] = child;
            if (child.children.length >= 1) {
                this.SerializableUIControlNode(child);
            }
        }
    }
}