import { _decorator, AssetManager, assetManager, Game, game, macro } from 'cc';
import { EGAME_TYPE, ENVIRONMENT } from '../../../scripts/common/define/EnumDefine';
import { Eventer } from '../../../scripts/framework/Eventer';
import { Entry } from '../../../scripts/framework/hall/entry/Entry';
import { BundleManager } from '../../../scripts/framework/manager/BundleManager';
import { CacheManager } from '../../../scripts/framework/manager/CacheManager';
import { UIManager } from '../../../scripts/framework/ui/UIManager';
import { Global } from '../../../scripts/main/Global';
import { GameCommonManager } from './GameCommonManager';
import { GameEventType } from './GameEventType';
import { GameLoadingView } from './gameLoading/GameLoadingView';
import GamesData from './GamesData';
import GameSocketManager from './gameSocket/GameSocketManager';
import { UIID_GAME } from './UIGameDefined';
import UIUtils from '../../../scripts/framework/ui/UIUtils';
import { GameModel } from '../../../scripts/main/GameModel';
import { Events } from '../../../scripts/framework/Events';
import { GameCommonModel } from './GameCommonModel';
import { GameComConst, GameFakeLoadState } from './constDatas/GameComConst';

export class GameBaseEntry extends Entry {

    /** 打开主视窗 */
    protected _isOpen: boolean;
    /** 游戏id */
    protected _gameId: number;
    /** 总文件数 */
    protected _totalFiles: number = 0;
    /** 已加载文件数 */
    protected _finishedFiles: number = 0;
    /** bundle加载完回调 */
    protected _bundleCompleteCb: Function;
    /** 虚假加载条的加载时间 */
    protected _fakeLoadTime: number = 1;
    /** 虚假加载条的状态 */
    protected _fakeLoadState: GameFakeLoadState = GameFakeLoadState.OFF;
    /** 虚假加载条的计时器 */
    protected _fakeLoadInterval: number;
    /** 虚假加载条的时间 */
    protected _fakeLoadIntervalTime: number = 0;

    /** 是否收到押注消息 */
    protected _isReceive: boolean;
    protected _loadBundleComCb: Function = null;

    constructor() {
        super();
    }

    onEnter(): void {
        super.onEnter();
        Eventer.getInstance().on(Events.LogoPlayEnd, this.logoPlayEnd, this);
        Eventer.getInstance().on(GameEventType.OnReceiveSlotInfo, this.setReceiveSlotInfo, this);
        game.on(Game.EVENT_SHOW, () => {
            GameSocketManager.getInstance().reLogin();
        });
    }

    onDestroy(): void {
        super.onDestroy();
        Eventer.getInstance().off(Events.LogoPlayEnd);
        Eventer.getInstance().off(GameEventType.OnReceiveSlotInfo);
    }

    protected initData(): void {
        this._gameId = Global.gameId;
    }

    protected loadResources(completeCb: () => void): void {
        if (GamesData.loadingRecord.hasOwnProperty(this._gameId)) {
            return;
        }

        this._bundleCompleteCb = completeCb;

        if (GameSocketManager.getInstance().isReConnect) {
            GameCommonManager.getInstance().startTimeMark();
        }

        let gameType: EGAME_TYPE = Global.gameType;
        GamesData.loadingRecord[this._gameId] = gameType;

        let bundle: AssetManager.Bundle = BundleManager.getInstance().getBundle(this._gameId.toString());
        bundle.loadDir(
            'resources',
            this.bundleLoadProgress.bind(this),
            this.bundleLoadComplete.bind(this)
        )
    }

    /**
     * bundle加载过程回调
     * @param finished 
     * @param total 
     * @param item 
     * @returns 
     */
    private bundleLoadProgress(finished: number, total: number, item: AssetManager.RequestItem) {
        if (GamesData.gameId != this._gameId) {
            return;
        }
        this._finishedFiles = finished;
        this._totalFiles = total;

        if (GameModel.getInstance().logoPlayed && this._fakeLoadState == GameFakeLoadState.OFF) {
            this.onProgress(finished, total);
        }
    }

    /**
     * bundle加载完成回调方法
     * @param err 
     * @param data 
     * @returns 
     */
    private bundleLoadComplete(err: Error | null, data: any) {
        delete GamesData.loadingRecord[this._gameId];

        if (GamesData.gameId != this._gameId) {
            this.removeBundle();
            return;
        }

        if (err)
            return;

        if (this._fakeLoadState != GameFakeLoadState.OFF)
            return;

        this.completeCb();
    }

    /** 回调 */
    private completeCb() {
        this._bundleCompleteCb();
        this.onComplete();
    }

    protected onProgress(finished: number, total: number): void {
        let loadingView: GameLoadingView = UIManager.getInstance().getUI(UIID_GAME.UIGameLoading) as GameLoadingView;
        if (!loadingView) {
            return;
        }
        loadingView.onProgress(finished, total);
    }

    protected onComplete(): void {
        let time = GamesData.totalLoadingTime;
        let enterType = GameSocketManager.getInstance().isReConnect ? 2 : 1;
        let platType = Global.osname;
        let obj = {
            gameid: Global.gameId,
            duration: time,
            enter_type: enterType,
            plat_type: platType
        }
        GameCommonManager.getInstance().c2javaMarkByShort('enter_time', obj);
        GamesData.optime = Date.now();
        let loadingView: GameLoadingView = UIManager.getInstance().getUI(UIID_GAME.UIGameLoading) as GameLoadingView;
        if (!loadingView) {
            return;
        }

        //检测LOGO 播放完再进入游戏
        if (GameModel.getInstance().logoPlayed)
            this.enterGame();
    }

    private logoPlayEnd() {
        this._fakeLoadState = GameFakeLoadState.ON;
        this.startFakeLoadInterval();
        this.enterGame();
    }

    /** 进入游戏 */
    private enterGame() {
        if (GameCommonModel.getInstance().isGameComEnter)
            return;
        GameCommonModel.getInstance().isGameComEnter = true;

        this.onLoadBundleComplete(() => {
            //回放
            if (Global.playback)
                return;

            //捕鱼
            if (Global.gameType != EGAME_TYPE.FISHING)
                GameSocketManager.getInstance().init(Global.webSocket);

            // if (Global.gameType == EGAME_TYPE.SLOTS) {
            //     UIManager.getInstance().open(UIID_GAME.ComView);
            //     //防止玩家同时触发购买免费和普通spin游戏
            //     macro.ENABLE_MULTI_TOUCH = false;
            // }

            if (!Global.premissionToEnterGame)
                UIUtils.showPopupView(40001);

            if (Global.platformId != ENVIRONMENT.DEV)
                UIManager.getInstance().open(UIID_GAME.UIComActMenu);

            // GameCommonManager.getInstance().showIntro();

        });
        Eventer.getInstance().emit(GameEventType.loadResourcesCom);
    }

    protected setReceiveSlotInfo(): void {
        this._isReceive = true;
        if (this._loadBundleComCb) {
            this._loadBundleComCb();
        }

    }

    /** 加载完毕后执行，需要游戏自己重写 */
    protected onLoadBundleComplete(cb: Function): void {
        this._loadBundleComCb = cb;
        Log.e("onLoadBundleComplete c2sSlotInfo =>");
        if (cb && this._isReceive) cb();
    }

    protected openGameView(): void {
        this._isOpen = true;
    }

    protected closeGameView(): void {
    }

    /** 启动虚假进度条计时器 */
    protected startFakeLoadInterval() {
        let callFunc = () => {
            this._fakeLoadIntervalTime += GameComConst.FAKE_LOAD_INTERVAL_TIME;
            //刷新进度
            let percent = this._fakeLoadIntervalTime / GameComConst.FAKE_LOAD_TIME;
            percent = Math.min(percent, 1);
            let fakeFilesNum = percent * this._finishedFiles;
            this.onProgress(fakeFilesNum, this._totalFiles);

            //检测结束
            if (this._fakeLoadIntervalTime >= GameComConst.FAKE_LOAD_TIME) {
                this.clearFakeLoadInterval();
                this._fakeLoadState = GameFakeLoadState.OFF;
                this.completeCb();
            }
        }

        //开启计时器
        callFunc();
        this._fakeLoadInterval = setInterval(callFunc, GameComConst.FAKE_LOAD_INTERVAL_TIME)
    }

    /** 清理虚假进度条计时器 */
    protected clearFakeLoadInterval() {
        if (this._fakeLoadInterval)
            clearInterval(this._fakeLoadInterval);
    }

    protected unloadResources(): void {
        super.unloadResources();

        if (this._isOpen) {
            this.removeBundle();
        }
        this._isOpen = false;
    }

    private removeBundle(): void {
        let bundle: AssetManager.Bundle = assetManager.getBundle(this._gameId.toString());
        if (bundle) {
            bundle.releaseAll();
            assetManager.removeBundle(bundle);
            CacheManager.getInstance().removeBundle(bundle);
        }
        GamesData.removeCommonBundle();
    }
}