const { ccclass, property } = _decorator;

@ccclass('LeagueTablesEntrance')
export class LeagueTablesEntrance extends UIButton {
    @property({ displayName: "phb_lab", type: Label })
    private phb_lab: Label;
    /**轮询时间 排行榜按钮是否显示 */
    private _pollingtime: number = 10000;

    private _rewardInfo: RewardInfoData;
    /**当期数据*/
    private _rewardNowInfo: RewardInfoData;
    private _time: number;
    readonly EndShowTime: number = 30 * 60 * 1000; // 30min
    public static instance = null
    init() {
        LeagueTablesEntrance.instance = this;
        if (!GamesData.rankingSwitch) {
            this.node.active = false;
            return;
        } else {
            this.node.active = true;
        }
        this._onEvent();
    }

    private _onEvent(): void {
        Eventer.getInstance().on(GameEventType.ACT_RANK_COUNT_DOWN, this._infoTime, this);
        Eventer.getInstance().on(GameEventType.ACT_RANK_INFO, this._infoNowTime, this);
        this.touchEndedFun = this._btnCall.bind(this);
        clearInterval(this._time);
        this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
        this._pollingEvent();
    }
    /**当期数据*/
    private _infoNowTime(message) {
        if (!message) return
        this._rewardNowInfo = new RewardInfoData();
        this._rewardNowInfo.startTime = message.startTime * 1000;
        this._rewardNowInfo.endTime = message.endTime * 1000;
        this._rewardNowInfo.rankId = message.rankId;

    }

    private _pollingEvent(): void {
        //Log.e("轮询状态中");
        GameCommonManager.getInstance().c2sGetRankCountDown();
        GameCommonManager.getInstance().c2sActRewardInfo();
    }

    /**活动是否开始*/
    private isStart
    private _infoTime(message: ActkRankInfoVo_s2c): void {
        //Log.w("入口", message)
        // message = { "countdownTime": 58601, "endTime": Global.svrTimeMS, "rankId": 171, "startTime": Global.svrTimeMS }
        if (!GamesData.rankingSwitch) {
            this.node.active = false;
            return;
        } else {
            this.node.active = true;
        }
        if (!message) {
            //this.node.active = false;
            return;
        }
        //Log.d("!GamesData.rankingSwitch", !GamesData.rankingSwitch)


        // this.node.active = true;

        clearInterval(this._time);
        this._rewardInfo = new RewardInfoData();
        this._rewardInfo.startTime = message.startTime * 1000;
        this._rewardInfo.endTime = message.endTime * 1000;
        this._rewardInfo.rankId = message.rankId;

        let localTime = Global.svrTimeMS;
        let endTime = this._rewardInfo.endTime;
        let startTime = this._rewardInfo.startTime;

        //Log.w("经过", giftTime, giftTime > -this.EndShowTime * 300000)
        if (!message.starting) {//活动未开始
            this.isStart = false
            // this.node.active = false;
            // this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
            // return;
        } else {
            this.isStart = true
        }
        let giftTime = this.isStart ? endTime - localTime : localTime - startTime;
        // if (giftTime > 0) {
        this._time = setInterval(this._updateTime.bind(this), 500);
        // }
        // else if (giftTime > -this.EndShowTime) {
        //     this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
        // }
        // else {
        // this.node.active = false;
        // this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
        // }

    }

    /**更新剩余时间 */
    private _updateTime() {
        if (!GamesData.rankingSwitch) {
            this.node.active = false;
            return;
        } else {
            this.node.active = true;
        }
        // this.node.active = true;

        let localTime = Global.svrTimeMS;
        let endTime = this._rewardInfo.endTime;
        let startTime = this._rewardInfo.startTime;
        let giftTime = this.isStart ? endTime - localTime : startTime - localTime;
        let timeStr: string;
        //Log.w("giftTime", giftTime)
        if (giftTime <= 0) {
            clearInterval(this._time);
            timeStr = "";
            this._time = setInterval(this._pollingEvent.bind(this), this._pollingtime);
        } else {
            timeStr = this._formatTime(giftTime);
        }
        // 根据排行榜是否进行显示不同的颜色
        this.phb_lab.color = new Color(238, 203, 147, 255)
        if (!this.isStart) {
            this.phb_lab.color = new Color(140, 159, 22, 255)
        }
        this.phb_lab.string = timeStr;
    }

    private offEvent(): void {
        if (this._time) {
            clearInterval(this._time);
        }
        Eventer.getInstance().offName(GameEventType.ACT_RANK_COUNT_DOWN, this);
        Eventer.getInstance().offName(GameEventType.ACT_RANK_INFO, this);
    }

    public onDestroy() {
        LeagueTablesEntrance.instance = null
        this.offEvent();
    }

    /**格式化时间 */
    public _formatTime(millisecond: number): string {
        let seconds = millisecond / 1000;
        let hours = Math.floor(seconds / 3600);
        if (hours >= 24) {
            let day = Math.floor(hours / 24);
            let daySrt = i18n.tr(1004012);
            return `${day} ${daySrt}`;
        }
        else {
            return this._countdown("hh:mm:ss", millisecond);
        }
    }

    private _countdown(fmt, millisecond) { //hh:mm:ss:SS
        let second = millisecond / 1000;
        var o = {
            "h+": Math.floor(second / 3600),
            "m+": Math.floor(second % 3600 / 60),
            "s+": Math.floor(second % 3600 % 60),
            "S+": Math.floor(millisecond % 1000 * 0.1),
        };

        for (var k in o) {
            if (new RegExp("(" + k + ")").test(fmt)) {
                fmt = fmt.replace(RegExp.$1, (RegExp.$1.length == 1) ? (o[k]) : (("00" + o[k]).substr(("" + o[k]).length)));
            }
        }

        return fmt;
    }

    private _btnCall(): void {
        UIManager.getInstance().open(UIID_GAME.UILeagueTables, this._rewardNowInfo);
        GameComUtils.c2sStat(StatConst.CLICK_RANK_ICONS);
    }

}

export class RewardInfoData {
    /**结束时间戳 */
    public endTime: number;
    /**开始时间戳 */
    public startTime: number;
    /**排行榜id */
    public rankId: number;
}

